      sha256 "d0eb565fb7f4266463698eb260f383dd15a3fbacd36a8690257dad09bffb8bce"
    else
      url "https://github.com/mumei-lang/mumei/releases/download/v0.6.12/mumei-x86_64-unknown-linux-gnu.tar.gz"
